function area(shape, d){
  switch(shape){
    case 'square': return d.s*d.s;
    case 'rectangle': return d.w*d.h;
    case 'triangle': return 0.5*d.b*d.h;
    case 'circle': return Math.PI*d.r*d.r;
    case 'ellipse': return Math.PI*d.a*d.b;
    case 'trapezoid': return 0.5*(d.a+d.b)*d.h;
    case 'parallelogram': return d.b*d.h;
    default: return NaN;
  }
}
var EXPORTS = { area:area };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AreaForgePure = EXPORTS; }
